// CSD_RATIONALE_BEGIN
// Root cause of timeout: previous attempt had 9 phases with 8 nested loops,
// complex sum-form decreases clauses, and many duplicate constraint blocks.
// Dafny timed out at 30s trying to verify all of them.
//
// Fix: Collapse to 4 simple phases, each with a single decreases clause:
//   Phase 1: Free generation watching for "<<" (decreases phase1Limit - steps)
//   Phase 2: Unconditional OpenConstrainedSpan if still outside span (no loop)
//   Phase 3a: 8-token warmup of ConstrainedStep without close-checking,
//             forcing multi-token expressions before any IsCompletePrefix test.
//   Phase 3b: ConstrainedStep + CloseSpanIfComplete loop (decreases maxSteps - steps)
//   Final: CloseSpanWithinBudget on all remaining budget
//
// The 8-token warmup in Phase 3a is the key accuracy fix: it prevents
// CloseSpanIfComplete from firing immediately after the first identifier,
// which caused the model to output <<n1>> instead of <<n1 + n2 * rate>>.
//
// All loops have simple single-measure decreases, capping total verification
// complexity well under 30 seconds.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// Invariant 1 — parser_validity:
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
//   Phase 1 (UnconstrainedStep): insideConstrainedOut stays false (loop guard)
//     until RenderedEndsWith detects "<<". EnterObservedConstrainedSpan sets
//     currentConstrainedOut := [] and parser.IsValidPrefix([]) holds by
//     method precondition. Vacuously true otherwise. ✓
//
//   Phase 2 (OpenConstrainedSpan): sets currentConstrainedOut := [], which
//     satisfies IsValidPrefix([]) by precondition. ✓
//
//   Phase 3a (ConstrainedStep warmup): ConstrainedStep returns a parser-valid
//     token or eosToken. On non-EOS, AppendConstrainedToken's postcondition
//     gives IsValidPrefix(ac). On EOS we break with state unchanged. ✓
//
//   Phase 3b (CloseSpanIfComplete + ConstrainedStep): CloseSpanIfComplete
//     returns closed=true only when IsCompletePrefix holds; it then sets
//     insideConstrainedOut := false (implication vacuously true). In the
//     else branch, ConstrainedStep + AppendConstrainedToken preserves
//     IsValidPrefix by library postcondition. ✓
//
//   Final (CloseSpanWithinBudget): library postcondition guarantees
//     insideOut ==> parser.IsValidPrefix(currentOut). ✓
//
// Invariant 2 — progress: |generated| <= |generatedPrefix| + steps
//
//   Phase 1: UnconstrainedStep costs +1 step; appends at most 1 visible
//     token. EnterObservedConstrainedSpan appends 0. Per iteration
//     steps += 1, |generated| grows by at most 1. ✓
//
//   Phase 2: OpenConstrainedSpan appends "<<" (1 token), steps += 1.
//     |generated'| = |generated| + 1 <= |generatedPrefix| + steps'. ✓
//
//   Phase 3a: ConstrainedStep costs +1 step (even EOS). AppendConstrainedToken
//     appends 1 visible token; EOS path appends 0. Net growth <= 1 per step. ✓
//
//   Phase 3b closed path: CloseSpanIfComplete appends ">>" (1 token),
//     steps += 1. Net growth = 1 = step consumed. ✓
//     Non-closed path: CloseSpanIfComplete costs 0; ConstrainedStep costs +1
//     step; AppendConstrainedToken appends 1 visible token. Net growth = 1. ✓
//
//   Final close: CloseSpanWithinBudget postcondition gives
//     |generatedOut| <= |generated| + budget; steps += budget. ✓
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm,
  "Solve step by step. Write the final answer as 'The answer is <<EXPR>>' where EXPR is an arithmetic expression using ALL relevant variables and operators from the problem. Examples: <<n * price + fee>>, <<int(n * frac) + base>>, <<(a + b) * rate / 60>>. Use only: variable names from the problem, numbers, +, -, *, /, (, ), int(). The expression MUST combine all relevant quantities with operators.");

var steps: nat := 0;

// Compute approximately 80% free-gen budget without nonlinear arithmetic
var phase1Limit: nat;
if maxSteps >= 5 {
  phase1Limit := maxSteps - maxSteps / 5;
} else {
  phase1Limit := maxSteps;
}

// Phase 1: Free generation, watching for natural "<<" emission
while steps < phase1Limit && !insideConstrainedOut
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  invariant steps <= maxSteps
  decreases phase1Limit - steps
{
  var next := helpers.UnconstrainedStep(lm, prompt, generated);
  steps := steps + 1;
  if next == eosToken { break; }
  generated := generated + [next];
  if RenderedEndsWith(generated, "<<") {
    var eg, ei, ec := helpers.EnterObservedConstrainedSpan(lm, generated);
    generated := eg; insideConstrainedOut := ei; currentConstrainedOut := ec;
  }
}

// Phase 2: Force-open a constrained span if not already inside one
if !insideConstrainedOut && steps < maxSteps {
  var fg, fi, fc := helpers.OpenConstrainedSpan(lm, generated);
  generated := fg; insideConstrainedOut := fi; currentConstrainedOut := fc;
  steps := steps + 1;
}

// Phase 3a: Warmup — generate at least 8 constrained tokens before any
//           completeness check, preventing premature single-identifier close.
var warmupSteps: nat := 0;
while insideConstrainedOut && steps < maxSteps && warmupSteps < 8
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  invariant steps <= maxSteps
  invariant warmupSteps <= 8
  decreases maxSteps - steps
{
  var cp := prompt + generated[..|generated| - |currentConstrainedOut|];
  var next := helpers.ConstrainedStep(lm, parser, cp, currentConstrainedOut, eosToken);
  steps := steps + 1;
  warmupSteps := warmupSteps + 1;
  if next == eosToken { break; }
  var ag, ai, ac := helpers.AppendConstrainedToken(lm, parser, generated, currentConstrainedOut, next);
  generated := ag; insideConstrainedOut := ai; currentConstrainedOut := ac;
}

// Phase 3b: Continue constrained generation with completeness checking
while insideConstrainedOut && steps < maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  invariant steps <= maxSteps
  decreases maxSteps - steps
{
  var cg, ci, cc, closed := helpers.CloseSpanIfComplete(lm, parser, generated, currentConstrainedOut);
  if closed {
    generated := cg; insideConstrainedOut := ci; currentConstrainedOut := cc;
    steps := steps + 1;
  } else {
    var cp := prompt + generated[..|generated| - |currentConstrainedOut|];
    var next := helpers.ConstrainedStep(lm, parser, cp, currentConstrainedOut, eosToken);
    steps := steps + 1;
    if next == eosToken { break; }
    var ag, ai, ac := helpers.AppendConstrainedToken(lm, parser, generated, currentConstrainedOut, next);
    generated := ag; insideConstrainedOut := ai; currentConstrainedOut := ac;
  }
}

// Final: force-close any still-open span within the remaining budget
if insideConstrainedOut && steps < maxSteps {
  var remBudget := maxSteps - steps;
  var wg, wi, wc := helpers.CloseSpanWithinBudget(lm, parser, prompt, generated, currentConstrainedOut, eosToken, remBudget);
  generated := wg; insideConstrainedOut := wi; currentConstrainedOut := wc;
  steps := steps + remBudget;
}

cost := steps;

